<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Midnight Ledger — a stealth heist in three floors</title>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #0a0d18; }
  #game {
    position: fixed; inset: 0; margin: auto;
    width: 1280px; height: 800px; max-width: 100vw; max-height: 100vh;
    display: block; touch-action: none; background: #10152a;
  }
  /* Read aloud, never shown: the status line screen readers announce. */
  #status { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
</style>
</head>
<body>
<canvas id="game" width="960" height="600" aria-label="Midnight Ledger: a top-down stealth heist. Move with WASD, sneak with Shift, interact with E, tools with Z, X and C."></canvas>
<p id="status" role="status" aria-live="polite"></p>
<script type="module" src="./src/main.js"></script>
</body>
</html>
