  bag: '#4a3520',
  cone: 'rgba(242, 178, 74, 0.20)',
  coneHot: 'rgba(230, 92, 60, 0.30)',
  cameraCone: 'rgba(120, 210, 235, 0.16)',
  cameraConeHot: 'rgba(230, 92, 60, 0.28)',
  laser: '#ff4b3e',
